lib='''def cells(grid, v):
    """All (r, c) positions holding color v."""
    return [(r, c) for r, row in enumerate(grid) for c, x in enumerate(row) if x == v]

def full_lines(grid, v):
    """Indices of rows (axis 0) and columns (axis 1) that are color v throughout, as (rows, cols)."""
    rows = [i for i, row in enumerate(grid) if set(row) == {v}]
    cols = [j for j in range(len(grid[0])) if {row[j] for row in grid} == {v}]
    return rows, cols

def paint(grid, r, c, v):
    """A copy of the grid with cell (r, c) set to v (grid unchanged if out of bounds)."""
    g = [row[:] for row in grid]
    if 0 <= r < len(g) and 0 <= c < len(g[0]):
        g[r][c] = v
    return g

def paint_soft(grid, r, c, v):
    """paint, but only onto background (0) cells."""
    if 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == 0:
        return paint(grid, r, c, v)
    return grid

def paint_cells(grid, cs, v, soft=False):
    """paint (or paint_soft) each (r, c) in cs with color v."""
    p = paint_soft if soft else paint
    for r, c in cs:
        grid = p(grid, r, c, v)
    return grid

def hbar(grid, r, v, soft=False):
    """The full-width horizontal bar of color v at row r."""
    return paint_cells(grid, [(r, c) for c in range(len(grid[0]))], v, soft)

def vbar(grid, c, v, soft=True):
    """The full-height vertical bar of color v at column c."""
    return paint_cells(grid, [(r, c) for r in range(len(grid))], v, soft)

def ring(grid, r, c, v, size=3, soft=True):
    """A size x size hollow square of color v centered at (r, c) (center cell untouched)."""
    k = size // 2
    cs = [(r + dr, c + dc) for dr in range(-k, k + 1) for dc in range(-k, k + 1)
          if abs(dr) == k or abs(dc) == k]
    return paint_cells(grid, cs, v, soft)

def find_rings(grid, border, center):
    """Centers (r, c) of size-3 rings with border color border and middle color center."""
    out = []
    for r, c in cells(grid, center):
        n = [(r + dr, c + dc) for dr in (-1, 0, 1) for dc in (-1, 0, 1) if (dr, dc) != (0, 0)]
        if all(0 <= a < len(grid) and 0 <= b < len(grid[0]) and grid[a][b] == border for a, b in n):
            out.append((r, c))
    return out
